package handler

import (
	"path/filepath"
	"strings"

	"github.com/hishack/go-codegen/config"
	"github.com/hishack/go-codegen/internal/field"
	"github.com/hishack/go-codegen/internal/merge"
)

// ApiGen 生成两类结构体文件:
//   - api 包:{domain}.go —— 请求结构体 + 响应别名(response.BaseResponse[T])
//   - vo 包:{domain}.go  —— 响应数据结构(含嵌套提升出来的结构体)
//
// 这两类文件由生成器全权管理(文件头带 DO NOT EDIT),字段与 yaml 严格同步
type ApiGen struct {
	cfg *config.CodeGenConfig
}

func NewApiGen(cfg *config.CodeGenConfig) *ApiGen { return &ApiGen{cfg: cfg} }

func (g *ApiGen) Name() string { return "api/vo" }

func (g *ApiGen) Generate(ctx *GenContext, report *Report) {
	for _, d := range groupDomains(ctx.Yamls) {
		if err := g.genApiFile(d, report); err != nil {
			report.warn("api 生成失败(" + d.Name + "): " + err.Error())
			continue
		}
		if err := g.genVoFile(d, report); err != nil {
			report.warn("vo 生成失败(" + d.Name + "): " + err.Error())
		}
	}
}

// ============ api 包 ============

func (g *ApiGen) genApiFile(d *domain, report *Report) error {
	path := filepath.Join(g.cfg.ApiOutPath, d.Name+".go")
	f, err := mergeGoFile(path, g.cfg.Module)
	if err != nil {
		return err
	}
	if !f.Exists() {
		f.SetPackage(pkgNameOfDir(g.cfg.ApiOutPath, "api"))
		f.SetHeader("Code generated by go-codegen. DO NOT EDIT.",
			"Author: "+g.cfg.UserName+"  Github: "+g.cfg.Github)
	}

	needTime := false
	for _, api := range d.Apis {
		// 请求结构体
		if api.HasReq() {
			for _, s := range structTypes(api.Req) {
				if hasTimeField(s) {
					needTime = true
				}
				a, err := f.UpsertType(structText(s, true), merge.PolicyAlways)
				if err != nil {
					return err
				}
				report.add(a)
			}
		}
		// 响应别名:type CreateUserResponse response.BaseResponse[T]
		if api.HasRes() {
			if api.ScalarRes() == nil {
				f.NeedImports(g.cfg.Module + "/internal/dal/vo")
			} else if t := api.ScalarRes(); typeUsesTime(t) {
				needTime = true
			}
			f.NeedImports(g.cfg.Module + "/pkg/response")
			a, err := f.UpsertType(g.aliasText(api), merge.PolicyAlways)
			if err != nil {
				return err
			}
			report.add(a)
		}
	}
	if needTime {
		f.NeedImports("time")
	}
	return writeMerge(f, report)
}

// aliasText 生成响应别名声明。
// 结构体 res: type CreateUserResponse response.BaseResponse[vo.CreateUserVo]
// 标量 res:   type DeleteUserResponse response.BaseResponse[bool]
func (g *ApiGen) aliasText(api *field.Api) string {
	var dataT string
	if t := api.ScalarRes(); t != nil {
		dataT = t.GoString()
	} else {
		dataT = "vo." + api.Res.Name
	}
	var b strings.Builder
	if api.Comment != "" {
		b.WriteString("// " + responseAlias(g.cfg, api) + " " + api.Comment + "响应\n")
	}
	b.WriteString("type " + responseAlias(g.cfg, api) + " response.BaseResponse[" + dataT + "]")
	return b.String()
}

// ============ vo 包 ============

func (g *ApiGen) genVoFile(d *domain, report *Report) error {
	path := filepath.Join(g.cfg.ModelOutPath, d.Name+".go")
	f, err := mergeGoFile(path, g.cfg.Module)
	if err != nil {
		return err
	}
	if !f.Exists() {
		f.SetPackage(pkgNameOfDir(g.cfg.ModelOutPath, "vo"))
		f.SetHeader("Code generated by go-codegen. DO NOT EDIT.",
			"Author: "+g.cfg.UserName+"  Github: "+g.cfg.Github)
	}

	needTime := false
	for _, api := range d.Apis {
		// 标量 res 不生成结构体
		if !api.HasRes() || api.ScalarRes() != nil {
			continue
		}
		for _, s := range structTypes(api.Res) {
			if hasTimeField(s) {
				needTime = true
			}
			a, err := f.UpsertType(structText(s, false), merge.PolicyAlways)
			if err != nil {
				return err
			}
			report.add(a)
		}
	}
	if needTime {
		f.NeedImports("time")
	}
	return writeMerge(f, report)
}

// ============ 结构体渲染 ============

// structText 渲染一个结构体声明。
// isReq=true 时字段 tag 带 form(hertz 的 query 绑定依赖 form 标签),vo 只要 json
func structText(s *field.Struct, isReq bool) string {
	var b strings.Builder
	if s.Comment != "" {
		b.WriteString("// " + s.Name + " " + s.Comment + "\n")
	}
	b.WriteString("type " + s.Name + " struct {\n")
	for _, fl := range s.Fields {
		if fl.Comment != "" {
			b.WriteString("\t// " + fl.Comment + "\n")
		}
		tag := `json:"` + fl.Tag + `"`
		if isReq {
			tag += ` form:"` + fl.Tag + `"`
		}
		b.WriteString("\t" + fl.Name + " " + fl.Type.GoString() + " `" + tag + "`\n")
	}
	b.WriteString("}")
	return b.String()
}

// hasTimeField 结构体(含嵌套)是否用到 time 包
func hasTimeField(s *field.Struct) bool {
	for _, fl := range s.Fields {
		if typeUsesTime(fl.Type) {
			return true
		}
	}
	return false
}

func typeUsesTime(t *field.Type) bool {
	if t == nil {
		return false
	}
	switch t.Kind {
	case field.KindPrimitive:
		return t.Name == "time.Time" || t.Name == "time.Duration"
	case field.KindSlice:
		return typeUsesTime(t.Elem)
	case field.KindMap:
		return typeUsesTime(t.Key) || typeUsesTime(t.Elem)
	}
	return false
}

// reqImports 已废弃:请求结构体只引用基础类型,无需跨包 import

// pkgNameOfDir 由输出目录推断包名:internal/dal/vo -> vo
func pkgNameOfDir(dir, fallback string) string {
	base := filepath.Base(strings.TrimRight(dir, "/\\"))
	if base == "" || strings.ContainsAny(base, " .") {
		return fallback
	}
	return base
}
